package com.cbs.payments;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.net.http.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;

class DarajaSandboxGatewayTest {
 private final UUID bank=UUID.randomUUID(),ledger=UUID.randomUUID();
 private MockEnvironment environment(){return new MockEnvironment().withProperty("cbs.payments.mpesa.enabled","true").withProperty("cbs.payments.mpesa.bank-id",bank.toString()).withProperty("cbs.payments.mpesa.settlement-ledger-id",ledger.toString()).withProperty("cbs.payments.mpesa.shortcode","600000").withProperty("cbs.payments.mpesa.consumer-key","fictional-key").withProperty("cbs.payments.mpesa.consumer-secret","fictional-secret").withProperty("cbs.payments.mpesa.initiator","fictional-initiator").withProperty("cbs.payments.mpesa.security-credential","fictional-encrypted").withProperty("cbs.payments.mpesa.callback-base","https://example.test");}
 @Test void sandboxConfigurationFailsClosedForProductionOtherBanksAndUnsafeCallback(){var env=environment();var gateway=new DarajaSandboxGateway(env);assertThat(gateway.binding(bank,ledger)).isTrue();assertThat(gateway.configured(UUID.randomUUID())).isFalse();assertThat(gateway.binding(bank,UUID.randomUUID())).isFalse();env.setActiveProfiles("production");assertThat(gateway.configured(bank)).isFalse();env.setActiveProfiles("development");env.setProperty("cbs.payments.mpesa.callback-base","http://example.test");assertThat(gateway.configured(bank)).isFalse();env.setProperty("cbs.payments.mpesa.callback-base","https://user:password@example.test");assertThat(gateway.configured(bank)).isFalse();env.setProperty("cbs.payments.mpesa.enabled","false");assertThat(gateway.configured(bank)).isFalse();}
 @Test void profilePinsBankLedgerAndProviderAccount(){var env=environment();var gateway=new DarajaSandboxGateway(env);String original=gateway.profile(bank);env.setProperty("cbs.payments.mpesa.shortcode","600001");assertThat(gateway.profile(bank)).isNotEqualTo(original);}
 @Test @SuppressWarnings("unchecked") void connectorUsesSandboxOAuthAndB2cWithoutAutomaticRetry()throws Exception{
  var http=mock(HttpClient.class);HttpResponse<String> auth=mock(HttpResponse.class),accepted=mock(HttpResponse.class);when(auth.statusCode()).thenReturn(200);when(auth.body()).thenReturn("{\"access_token\":\"fictional-token\"}");when(accepted.statusCode()).thenReturn(200);when(accepted.body()).thenReturn("{\"ResponseCode\":\"0\",\"ConversationID\":\"conv-1\",\"OriginatorConversationID\":\"orig-1\"}");when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(auth,accepted);
  var gateway=new DarajaSandboxGateway(environment(),http);var order=new PaymentModels.Order(1,UUID.randomUUID(),ledger,"100","254700000001","Fictional",java.time.LocalDate.of(2026,10,7),"TEST-1","Fictional payment");assertThat(gateway.transfer(bank,UUID.randomUUID(),order,"a".repeat(64)).originatorId()).isEqualTo("orig-1");
  var calls=org.mockito.ArgumentCaptor.forClass(HttpRequest.class);verify(http,times(2)).send(calls.capture(),any(HttpResponse.BodyHandler.class));assertThat(calls.getAllValues().getFirst().uri().toString()).isEqualTo("https://sandbox.safaricom.co.ke/oauth/v1/generate?grant_type=client_credentials");var request=calls.getAllValues().getLast();assertThat(request.uri().toString()).isEqualTo("https://sandbox.safaricom.co.ke/mpesa/b2c/v1/paymentrequest");assertThat(request.method()).isEqualTo("POST");assertThat(request.headers().firstValue("Authorization")).contains("Bearer fictional-token");
  when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenThrow(new java.io.IOException("Timeout"));assertThatThrownBy(()->gateway.transfer(bank,UUID.randomUUID(),order,"b".repeat(64))).isInstanceOf(com.cbs.tenancy.TenantException.class).hasMessageContaining("investigate");verify(http,times(3)).send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class));
 }
 @Test void callbackParsingKeepsOnlyBoundedObservationFields(){var result=PaymentService.parseCallback("{\"Result\":{\"ResultCode\":0,\"ConversationID\":\"c1\",\"OriginatorConversationID\":\"o1\",\"TransactionID\":\"R1\",\"ResultDesc\":\"Ignored personal information\",\"ResultParameters\":{\"ResultParameter\":[{\"Key\":\"TransactionAmount\",\"Value\":100}]}}}");assertThat(result.amount()).isEqualTo("100");assertThat(result.toString()).doesNotContain("personal");assertThatThrownBy(()->PaymentService.parseCallback("{\"Result\":{\"ResultCode\":0}} ")).isInstanceOf(com.cbs.tenancy.TenantException.class);assertThatThrownBy(()->PaymentService.parseCallback("invalid")).isInstanceOf(com.cbs.tenancy.TenantException.class);}
}
